import random
from itertools import combinations

import pytest

from mitm import count_subsets, subset_exists


# ---------------------------------------------------------------- oracle

def brute_count(nums, target):
    """Oracle for n <= 20: count all subsets (incl. empty) summing to target."""
    n = len(nums)
    total = 0
    for r in range(n + 1):
        for combo in combinations(range(n), r):
            if sum(nums[i] for i in combo) == target:
                total += 1
    return total


def brute_exists(nums, target):
    return brute_count(nums, target) > 0


def achievable_sums(nums):
    sums = {0}
    for v in nums:
        sums |= {s + v for s in sums}
    return sums


# ------------------------------------------------------- random instances

def make_instance(rng):
    n = rng.randint(0, 20)
    nums = [rng.randint(-50, 50) for _ in range(n)]
    ach = sorted(achievable_sums(nums))
    # one achievable target, one very likely unachievable
    t_hit = rng.choice(ach)
    t_miss = rng.randint(-2000, 2000)
    return nums, t_hit, t_miss


@pytest.fixture(scope="module")
def instances():
    rng = random.Random(20260824)
    return [make_instance(rng) for _ in range(300)]


def test_subset_exists_matches_oracle(instances):
    for nums, t_hit, t_miss in instances:
        assert subset_exists(nums, t_hit) is True
        assert subset_exists(nums, t_hit) == brute_exists(nums, t_hit)
        assert subset_exists(nums, t_miss) == brute_exists(nums, t_miss)


def test_count_subsets_matches_oracle(instances):
    for nums, t_hit, t_miss in instances:
        assert count_subsets(nums, t_hit) == brute_count(nums, t_hit)
        assert count_subsets(nums, t_miss) == brute_count(nums, t_miss)
        assert (count_subsets(nums, t_hit) > 0) == subset_exists(nums, t_hit)


# ------------------------------------------------------------- edge cases

def test_empty_input():
    assert subset_exists([], 0) is True      # empty subset sums to 0
    assert subset_exists([], 1) is False
    assert count_subsets([], 0) == 1         # empty subset counts once
    assert count_subsets([], 7) == 0


def test_target_zero_counts_empty_subset():
    assert count_subsets([3, -3], 0) >= 2    # {} and {3,-3}
    assert count_subsets([], 0) == 1
    assert count_subsets([5, 6], 0) == 1     # only {}
    assert subset_exists([5, 6], 0) is True


def test_all_negative():
    nums = [-50, -30, -20]
    assert subset_exists(nums, -50)
    assert subset_exists(nums, -100)         # -30 + -20 + -50
    assert not subset_exists(nums, 10)
    assert count_subsets([-1, -2, -3], -3) == 2  # {-3} and {-1,-2}
    assert count_subsets([-4, -4], -8) == 1
    assert count_subsets([-5], -5) == 1


def test_duplicates_and_zero_values():
    assert count_subsets([0, 0, 0], 0) == 8  # every mask over three zeros
    assert subset_exists([7, 7, 7], 14)


# ------------------------------------------------------------ performance

def test_perf_n40_under_5s():
    import time
    rng = random.Random(42)
    nums = [rng.randint(-10**9, 10**9) for _ in range(40)]
    target = sum(nums[:20]) - sum(nums[20:])  # guaranteed achievable
    start = time.perf_counter()
    ok = subset_exists(nums, target)
    elapsed = time.perf_counter() - start
    assert ok
    assert elapsed < 5.0, f"took {elapsed:.3f}s"

